"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["7628"],{6075(e,n,t){t.r(n),t.d(n,{metadata:()=>s,default:()=>u,frontMatter:()=>r,contentTitle:()=>c,toc:()=>l,assets:()=>d});var s=JSON.parse('{"id":"m8-config-rbac-microservices/lesson-1-config-access-control","title":"Lesson 1: Configuration & Access Control","description":"By now Fernwood Goods runs entirely on the cluster. A frontend Deployment, a backend Deployment, a","source":"@site/docs/m8-config-rbac-microservices/lesson-1-config-access-control.md","sourceDirName":"m8-config-rbac-microservices","slug":"/m8-config-rbac-microservices/lesson-1-config-access-control","permalink":"/k8s-distributed-systems/docs/m8-config-rbac-microservices/lesson-1-config-access-control","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson 1: Configuration & Access Control"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/k8s-distributed-systems/docs/m7-envoy-ingress/deep-dive"},"next":{"title":"Lesson 2: The Microservices Outlook","permalink":"/k8s-distributed-systems/docs/m8-config-rbac-microservices/lesson-2-microservices-outlook"}}'),o=t(4848),i=t(8453),a=t(7684);let r={sidebar_position:1,title:"Lesson 1: Configuration & Access Control"},c="Configuration & Access Control",d={},l=[{value:"The analogy: a secured research campus",id:"the-analogy-a-secured-research-campus",level:2},{value:"Externalizing configuration: ConfigMaps and Secrets",id:"externalizing-configuration-configmaps-and-secrets",level:2},{value:"Three gates: authentication, authorization, admission control",id:"three-gates-authentication-authorization-admission-control",level:2},{value:"Service Accounts: identity for Pods",id:"service-accounts-identity-for-pods",level:2},{value:"RBAC: Roles, ClusterRoles, and bindings",id:"rbac-roles-clusterroles-and-bindings",level:2},{value:"NetworkPolicy: closing the flat network",id:"networkpolicy-closing-the-flat-network",level:2},{value:"Where this leaves the app",id:"where-this-leaves-the-app",level:2}];function h(e){let n={admonition:"admonition",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"configuration--access-control",children:"Configuration & Access Control"})}),"\n",(0,o.jsx)(a.A,{src:"decks/m8-config-access-control.html",title:"M8 \u2014 Configuration & Access Control"}),"\n",(0,o.jsx)(n.p,{children:"By now Fernwood Goods runs entirely on the cluster. A frontend Deployment, a backend Deployment, a\nPostgres StatefulSet, Services wiring them together, and an Envoy front door letting the outside world in.\nIt works. But two things are still wide open, and both would fail a production review."}),"\n",(0,o.jsx)(n.p,{children:"First, the app's configuration is stitched into the wrong places. The backend's database host was a raw\nvalue typed straight into the Deployment manifest back in M6. The database password lives in plain sight in\nthe StatefulSet. To point the same image at a different database you would edit YAML and redeploy. That is\nconfig welded to the workload, and it is the first thing an auditor flags."}),"\n",(0,o.jsx)(n.p,{children:"Second, the cluster trusts everyone completely. Any Pod can open a connection to any other Pod \u2014 the\nfrontend could talk straight to Postgres, a debug Pod could reach the database, nothing stops it. And any\nperson or process holding a kubeconfig can do anything: read every Secret, delete any Deployment, in any\nnamespace. A flat, fully-trusting cluster is fine on your laptop and dangerous the moment more than one\nteam shares it."}),"\n",(0,o.jsxs)(n.p,{children:["This lesson closes both gaps. You will pull configuration out of the workload into ",(0,o.jsx)(n.strong,{children:"ConfigMaps"})," and\n",(0,o.jsx)(n.strong,{children:"Secrets"}),", then learn the three access-control systems Kubernetes uses to decide who may do what:\n",(0,o.jsx)(n.strong,{children:"authentication, authorization, and admission control"}),", the ",(0,o.jsx)(n.strong,{children:"RBAC"})," model that expresses permissions,\nand ",(0,o.jsx)(n.strong,{children:"NetworkPolicy"}),", which finally restricts which Pods may talk to which."]}),"\n",(0,o.jsx)(n.h2,{id:"the-analogy-a-secured-research-campus",children:"The analogy: a secured research campus"}),"\n",(0,o.jsx)(n.p,{children:"Think about a large research campus \u2014 several buildings, hundreds of staff, some work highly sensitive.\nNobody memorizes how the campus runs. There are two very different things going on, and it helps to keep\nthem apart from the start."}),"\n",(0,o.jsxs)(n.p,{children:["The first is ",(0,o.jsx)(n.strong,{children:"configuration"}),". Every workstation has a printed ",(0,o.jsx)(n.strong,{children:"standing-orders sheet"})," taped beside it:\nwhich server to log into, which printer to use, which project code to bill. The truly sensitive values \u2014\ndoor codes, vault combinations \u2014 are not on that sheet; they are in a ",(0,o.jsx)(n.strong,{children:"sealed envelope"})," in a locked\ndrawer. The key insight is that the ",(0,o.jsx)(n.em,{children:"worker"})," and the ",(0,o.jsx)(n.em,{children:"instructions"})," are separate. A new hire sits down,\nreads the sheet, and gets to work. Move them to another project and you swap the sheet, not the person."]}),"\n",(0,o.jsxs)(n.p,{children:["The second is ",(0,o.jsx)(n.strong,{children:"access control"}),", and the campus runs it in three checks. A ",(0,o.jsx)(n.strong,{children:"guard at the gate"})," verifies\nwho you are against your ID \u2014 that is ",(0,o.jsx)(n.strong,{children:"authentication"}),". Your ",(0,o.jsx)(n.strong,{children:"badge's clearance level"})," then decides\nwhich doors actually open for you \u2014 that is ",(0,o.jsx)(n.strong,{children:"authorization"}),". And a ",(0,o.jsx)(n.strong,{children:"mailroom inspection"})," examines\nanything you try to bring in, and can reject it or stamp a correction on it before it goes further \u2014 that\nis ",(0,o.jsx)(n.strong,{children:"admission control"}),". Three separate checks, in order: ",(0,o.jsx)(n.em,{children:"who are you"}),", ",(0,o.jsx)(n.em,{children:"what are you allowed to do"}),", and\n",(0,o.jsx)(n.em,{children:"is what you are asking for acceptable"}),"."]}),"\n",(0,o.jsxs)(n.p,{children:["Two more campus facts matter. Automated equipment \u2014 a delivery robot, a sensor rig \u2014 also needs a badge; it\ngets a ",(0,o.jsx)(n.strong,{children:"machine credential"}),", not a person's ID. And inside the buildings, not every corridor connects to\nevery room: sealed doors keep the isolation wing reachable only from the wards that should reach it. Hold\nthat whole picture; the rest of the lesson is just the Kubernetes name for each part of it."]}),"\n",(0,o.jsx)(n.h2,{id:"externalizing-configuration-configmaps-and-secrets",children:"Externalizing configuration: ConfigMaps and Secrets"}),"\n",(0,o.jsx)(n.p,{children:"Back in M6 you wired the backend to Postgres by typing the database's DNS name directly into the\nDeployment:"}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-yaml",children:'env:\n  - name: DB_HOST\n    value: "db-0.db.fernwood.svc.cluster.local"\n'})}),"\n",(0,o.jsxs)(n.p,{children:["That worked, and for one value it was fine. But think about what it means. The address of a ",(0,o.jsx)(n.em,{children:"backing\nservice"})," is now baked into the ",(0,o.jsx)(n.em,{children:"workload definition"}),". The backend image already reads five settings from\nits environment \u2014 ",(0,o.jsx)(n.code,{children:"DB_HOST"}),", ",(0,o.jsx)(n.code,{children:"DB_PORT"}),", ",(0,o.jsx)(n.code,{children:"DB_NAME"}),", ",(0,o.jsx)(n.code,{children:"DB_USER"}),", ",(0,o.jsx)(n.code,{children:"DB_PASSWORD"}),". If every one of those is a\nliteral in the manifest, then the manifest is specific to one environment. Staging has a different database\nhost; production has a different password. You end up with three near-identical manifests that differ only\nin a few strings, and every difference is a chance to ship the wrong one."]}),"\n",(0,o.jsxs)(n.p,{children:["The rule underneath this is worth stating plainly: ",(0,o.jsx)(n.strong,{children:"configuration that changes between environments does\nnot belong in the image, and it does not belong hardcoded in the workload either."})," The image is built\nonce and should run unchanged everywhere. What changes per environment is data the workload reads at\nstartup. Kubernetes gives you two objects to hold that data."]}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.strong,{children:"ConfigMap"})," holds non-secret configuration as key/value pairs. This is the standing-orders sheet: the\ndatabase host, port, name, user \u2014 settings you would not mind someone reading. A ",(0,o.jsx)(n.strong,{children:"Secret"})," holds the\nvalues you would never print on a sheet \u2014 here, the database password. It is the sealed envelope."]}),"\n",(0,o.jsxs)(n.p,{children:["Here is the honest truth about Secrets, and it catches people: ",(0,o.jsx)(n.strong,{children:"a Secret is not encrypted by default."}),"\nIts values are base64-encoded, which is ",(0,o.jsx)(n.em,{children:"encoding, not encryption"})," \u2014 anyone can decode it in one command.\nSo what does a Secret actually buy you over a ConfigMap? Two real things. It is a ",(0,o.jsx)(n.strong,{children:"separate object with\nits own RBAC"}),", so you can let a team read the ConfigMap while denying them the Secret. And it is handled\nmore carefully by the platform \u2014 kept out of most logs, mountable as an in-memory file, and encryptable at\nrest if the cluster enables it. The separation is the point: secrets and non-secrets get different\npermissions because they carry different risk."]}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart LR\n  subgraph img [Built once, runs everywhere]\n    I[backend image<br/>reads DB_* from env]\n  end\n  CM[ConfigMap backend-config<br/>DB_HOST, DB_PORT, DB_NAME, DB_USER] --\x3e|envFrom| I\n  S[Secret backend-secret<br/>DB_PASSWORD] --\x3e|envFrom| I"}),"\n",(0,o.jsxs)(n.p,{children:["The workload pulls both in with ",(0,o.jsx)(n.code,{children:"envFrom"}),", which injects ",(0,o.jsx)(n.strong,{children:"every"})," key in the object as an environment\nvariable of the same name. Because the backend already reads ",(0,o.jsx)(n.code,{children:"DB_HOST"}),", ",(0,o.jsx)(n.code,{children:"DB_NAME"})," and the rest from its\nenvironment, the keys line up and nothing in the application code changes. The Deployment's env block that\nused to hold a literal ",(0,o.jsx)(n.code,{children:"DB_HOST"})," becomes two references:"]}),"\n",(0,o.jsx)(n.pre,{children:(0,o.jsx)(n.code,{className:"language-yaml",children:"envFrom:\n  - configMapRef:\n      name: backend-config\n  - secretRef:\n      name: backend-secret\n"})}),"\n",(0,o.jsxs)(n.p,{children:["That is the whole move. The image is untouched. The behavior is identical \u2014 the app still reports\n",(0,o.jsx)(n.code,{children:"db: connected"}),". But the configuration now lives in objects you can review, diff, and permission\nseparately from the workload, and the same image will run against any database by swapping the ConfigMap\nand Secret. When you need a single value in one specific place rather than the whole set, ",(0,o.jsx)(n.code,{children:"valueFrom"})," pulls\none key (",(0,o.jsx)(n.code,{children:"configMapKeyRef"})," or ",(0,o.jsx)(n.code,{children:"secretKeyRef"}),") instead of the wholesale ",(0,o.jsx)(n.code,{children:"envFrom"})," \u2014 you will use both."]}),"\n",(0,o.jsx)(n.admonition,{title:"Config drift is a real failure mode",type:"note",children:(0,o.jsxs)(n.p,{children:["When a Pod reads config through ",(0,o.jsx)(n.code,{children:"envFrom"}),", it reads it ",(0,o.jsx)(n.strong,{children:"once, at container start"}),". Editing the ConfigMap\nlater does not change a running Pod \u2014 you must roll the Deployment for the new values to take effect. That\nis not a bug; it is why a config change is a deploy, not a silent live edit. It also means a Pod stuck\nreferencing a key that no longer exists fails to start at all, which is one of the drills in this module's\ndeep dive."]})}),"\n",(0,o.jsx)(n.h2,{id:"three-gates-authentication-authorization-admission-control",children:"Three gates: authentication, authorization, admission control"}),"\n",(0,o.jsxs)(n.p,{children:["Now to access control. Every request to the Kubernetes API server \u2014 every ",(0,o.jsx)(n.code,{children:"kubectl"}),' command, every Pod\nusing its token \u2014 passes through three stages in a fixed order before it is allowed to change anything.\nThese are the guard, the badge reader, and the mailroom from the analogy, and keeping them distinct is what\nlets you debug a "permission" problem correctly.']}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart LR\n  R[Request<br/>kubectl / Pod token] --\x3e A{AuthN<br/>who are you?}\n  A --\x3e|verified identity| Z{AuthZ<br/>are you allowed?}\n  A --\x3e|unknown| X1[401 Unauthorized]\n  Z --\x3e|permitted| AD{Admission<br/>is it acceptable?}\n  Z --\x3e|denied| X2[403 Forbidden]\n  AD --\x3e|accepted / mutated| DB[(persisted to etcd)]\n  AD --\x3e|rejected| X3[request rejected]"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Authentication (authN)"})," answers ",(0,o.jsx)(n.em,{children:"who are you?"}),' The API server verifies the caller\'s identity from the\ncredential they present \u2014 a client certificate, a bearer token, or, for a Pod, its Service Account token.\nKubernetes has no built-in "user" object for humans; it trusts an external identity source and reads the\nidentity off the credential. If the credential is invalid, the request stops here with ',(0,o.jsx)(n.code,{children:"401"}),". Note what\nauthN does ",(0,o.jsx)(n.strong,{children:"not"})," do: it does not decide what you can do. The guard confirms your ID; it does not open any\ndoors."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Authorization (authZ)"})," answers ",(0,o.jsx)(n.em,{children:"are you allowed to do this?"})," Now that the API server knows who you are,\nit checks whether that identity may perform this specific verb on this specific resource in this specific\nnamespace \u2014 ",(0,o.jsx)(n.code,{children:"delete pods in fernwood"}),", ",(0,o.jsx)(n.code,{children:"get secrets in kube-system"}),". In this course, and in almost every\nreal cluster, the system doing that checking is ",(0,o.jsx)(n.strong,{children:"RBAC"}),". If no rule permits the action, the request stops\nhere with ",(0,o.jsx)(n.code,{children:"403 Forbidden"}),". This is the badge reader: identity already known, now the question is clearance."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Admission control"})," answers ",(0,o.jsx)(n.em,{children:"is what you are asking for acceptable, and should it be adjusted?"})," Even a\nfully-authorized request can be rejected or modified at this last gate by admission controllers \u2014 the\nmailroom inspection. ",(0,o.jsx)(n.strong,{children:"Mutating"})," admission can change the request (inject a sidecar, set a default,\nadd a label); ",(0,o.jsx)(n.strong,{children:"validating"}),' admission can veto it against a policy ("every Pod must set resource limits",\n"no privileged containers"). This is how a platform team enforces standards that RBAC cannot express \u2014 RBAC\nsays ',(0,o.jsx)(n.em,{children:"who"})," may act, admission says ",(0,o.jsx)(n.em,{children:"what shape"})," the result must have. Only after all three gates does the\nchange land in etcd."]}),"\n",(0,o.jsxs)(n.p,{children:['The reason to hold these apart: when something is "denied," the stage tells you the cause. A ',(0,o.jsx)(n.code,{children:"401"})," is an\nidentity problem (bad or missing credential). A ",(0,o.jsx)(n.code,{children:"403"})," is an RBAC problem (identity fine, permission\nmissing). A rejection with a policy message is admission (permission fine, the object violates a rule).\nThree different fixes."]}),"\n",(0,o.jsx)(n.h2,{id:"service-accounts-identity-for-pods",children:"Service Accounts: identity for Pods"}),"\n",(0,o.jsxs)(n.p,{children:["Humans authenticate with certificates or tokens from an external identity provider. But a Pod also makes\nAPI calls \u2014 a controller reconciling objects, the ingress controller reading Ingress rules, your own app\nlisting Pods. What identity does ",(0,o.jsx)(n.em,{children:"it"})," use? That is the machine credential from the analogy: a ",(0,o.jsx)(n.strong,{children:"Service\nAccount"}),"."]}),"\n",(0,o.jsxs)(n.p,{children:["A Service Account is an identity for workloads, native to Kubernetes and namespaced. Every Pod runs as\none \u2014 if you do not name it, the Pod uses the ",(0,o.jsx)(n.code,{children:"default"})," Service Account in its namespace. Kubernetes mounts\na token for that Service Account into the Pod, and when the Pod calls the API server, that token is its\ncredential; the API server authenticates the call as ",(0,o.jsx)(n.code,{children:"system:serviceaccount:<namespace>:<name>"}),". This is\nthe same as a person's ID badge, except it is issued to a process, not a person, and it is confined to one\nnamespace."]}),"\n",(0,o.jsxs)(n.p,{children:["The security lesson here is the same as least privilege everywhere: the ",(0,o.jsx)(n.code,{children:"default"})," Service Account should be\nable to do almost nothing, and any Pod that genuinely needs API access should run as a ",(0,o.jsx)(n.strong,{children:"purpose-made\nService Account"})," granted exactly the permissions it needs \u2014 no more. In the lab you create a Service\nAccount that can only read Pods in ",(0,o.jsx)(n.code,{children:"fernwood"}),", and prove it can do that and nothing else."]}),"\n",(0,o.jsx)(n.h2,{id:"rbac-roles-clusterroles-and-bindings",children:"RBAC: Roles, ClusterRoles, and bindings"}),"\n",(0,o.jsxs)(n.p,{children:['Authorization needs a language for "who may do what, where." That language is ',(0,o.jsx)(n.strong,{children:"Role-Based Access Control"}),",\nand it is built from just two kinds of object: ones that ",(0,o.jsx)(n.strong,{children:"define a set of permissions"}),", and ones that\n",(0,o.jsx)(n.strong,{children:"grant that set to a subject"}),". A subject is a user, a group, or a Service Account."]}),"\n",(0,o.jsx)(n.p,{children:"The permission-defining objects come in a namespaced and a cluster-wide form, and this split maps straight\nonto the namespaces you learned in M4:"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["A ",(0,o.jsx)(n.strong,{children:"Role"}),' is namespaced. Its rules apply only inside one namespace. "Read Pods in ',(0,o.jsx)(n.code,{children:"fernwood"}),'" is a Role.\nThis is the wing-specific badge \u2014 it opens doors in one wing only.']}),"\n",(0,o.jsxs)(n.li,{children:["A ",(0,o.jsx)(n.strong,{children:"ClusterRole"})," is cluster-scoped. The same kind of rules, but they apply cluster-wide, and a\nClusterRole can also grant access to cluster-scoped resources (Nodes, PersistentVolumes, namespaces\nthemselves) that a Role cannot even name. This is the facility-wide badge."]}),"\n"]}),"\n",(0,o.jsxs)(n.p,{children:["A Role or ClusterRole on its own grants nothing \u2014 it is a definition sitting on a shelf. The ",(0,o.jsx)(n.strong,{children:"binding"}),"\nattaches it to a subject:"]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["A ",(0,o.jsx)(n.strong,{children:"RoleBinding"})," grants a Role (or a ClusterRole) ",(0,o.jsx)(n.strong,{children:"within one namespace"}),'. It says "this subject has\nthese permissions, here."']}),"\n",(0,o.jsxs)(n.li,{children:["A ",(0,o.jsx)(n.strong,{children:"ClusterRoleBinding"})," grants a ClusterRole ",(0,o.jsx)(n.strong,{children:"across the whole cluster"}),"."]}),"\n"]}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart TD\n  subgraph def [Define permissions]\n    RO[Role<br/>namespaced rules]\n    CR[ClusterRole<br/>cluster-wide rules]\n  end\n  subgraph grant [Grant to a subject]\n    RB[RoleBinding<br/>in one namespace]\n    CRB[ClusterRoleBinding<br/>whole cluster]\n  end\n  SA[ServiceAccount<br/>pod-reader] --\x3e RB\n  RO --\x3e RB\n  CR -.reuse cluster-wide rules<br/>but scope to one ns.-> RB\n  CR --\x3e CRB"}),"\n",(0,o.jsxs)(n.p,{children:["One combination is worth calling out because it is genuinely useful: a ",(0,o.jsx)(n.strong,{children:"RoleBinding can reference a\nClusterRole"}),'. That lets the platform team define a reusable permission set once as a ClusterRole (say,\n"read-only across common resources") and then grant it ',(0,o.jsx)(n.em,{children:"namespace by namespace"})," with RoleBindings \u2014 the\npermission is scoped to wherever the binding lives, not cluster-wide. Define once, grant narrowly."]}),"\n",(0,o.jsxs)(n.p,{children:["The discipline that makes RBAC safe is ",(0,o.jsx)(n.strong,{children:"least privilege"}),": grant the narrowest verbs (",(0,o.jsx)(n.code,{children:"get"}),", ",(0,o.jsx)(n.code,{children:"list"}),") on\nthe fewest resources (",(0,o.jsx)(n.code,{children:"pods"}),") in the smallest scope (one namespace) that does the job. It is far easier to\nadd a permission when something legitimately needs it than to discover, during an incident, that a\nService Account could delete production because someone bound ",(0,o.jsx)(n.code,{children:"cluster-admin"})," to be safe. In the lab you\nwill feel this directly: a Service Account that can list Pods but gets a hard ",(0,o.jsx)(n.code,{children:"Forbidden"})," the instant it\ntries to delete one."]}),"\n",(0,o.jsx)(n.h2,{id:"networkpolicy-closing-the-flat-network",children:"NetworkPolicy: closing the flat network"}),"\n",(0,o.jsxs)(n.p,{children:["The last gap is the network itself. Go all the way back to M1: Docker gave every container on a bridge a\nflat network where everyone could reach everyone. That default carried into Kubernetes \u2014 by default,\n",(0,o.jsx)(n.strong,{children:"every Pod can open a connection to every other Pod"}),", across namespaces, with nothing in the way. The\nfrontend could connect straight to Postgres. A debug Pod someone left running could reach the database.\nNothing is stopping it, because nothing has been told to."]}),"\n",(0,o.jsxs)(n.p,{children:["A ",(0,o.jsx)(n.strong,{children:"NetworkPolicy"})," changes the default from open to closed, then reopens only the paths you name. It is\nthe sealed internal doors of the campus: the isolation wing is reachable only from the wards that should\nreach it, and every other corridor to it is walled off."]}),"\n",(0,o.jsxs)(n.p,{children:["Two facts decide whether a NetworkPolicy does anything at all. First, policies are ",(0,o.jsx)(n.strong,{children:"additive and\ndefault-deny-on-selection"}),": the moment ",(0,o.jsx)(n.em,{children:"any"})," policy selects a Pod for a direction (ingress or egress),\nthat Pod denies all traffic in that direction ",(0,o.jsx)(n.em,{children:"except"})," what some policy explicitly allows. A Pod that no\npolicy selects stays wide open. So the standard pattern is a ",(0,o.jsx)(n.strong,{children:"default-deny"})," policy that selects every Pod\nand permits nothing, followed by narrow allow-policies that add back exactly the wanted paths."]}),"\n",(0,o.jsxs)(n.p,{children:["Second \u2014 and this is why the course's cluster is built the way it is \u2014 ",(0,o.jsx)(n.strong,{children:"NetworkPolicy is enforced by the\nCNI plugin, not by Kubernetes core."})," The API server will happily accept a NetworkPolicy object under a CNI\nthat ignores it, and you will believe you are protected while every packet still flows. This course's KIND\ncluster runs ",(0,o.jsx)(n.strong,{children:"Calico"})," precisely because the default kindnet CNI does ",(0,o.jsx)(n.strong,{children:"not"})," enforce NetworkPolicy. That\ndecision, made back in M3, is what makes this lesson real instead of theatre."]}),"\n",(0,o.jsx)(n.p,{children:"For Fernwood the intended shape is a simple chain plus the ingress exception:"}),"\n",(0,o.jsx)(n.mermaid,{value:"flowchart LR\n  ENV[Envoy / projectcontour] --\x3e|:3000| FE[frontend Pods]\n  ENV --\x3e|:8080| BE[backend Pods]\n  FE --\x3e|:8080| BE\n  BE --\x3e|:5432| DB[(db Pods)]\n  X[any other Pod] -.blocked.-> BE\n  X -.blocked.-> DB"}),"\n",(0,o.jsxs)(n.p,{children:["Default-deny everything, then allow: the frontend reachable from Envoy on 3000; the backend reachable from\nthe frontend ",(0,o.jsx)(n.em,{children:"and"})," Envoy on 8080; the database reachable from the backend and nothing else on 5432. Every\nother path \u2014 a stray Pod dialling the backend, anyone at all dialling Postgres \u2014 is dropped."]}),"\n",(0,o.jsxs)(n.p,{children:["That ingress exception for Envoy is not optional. The whole front door you built in M7 depends on Envoy\nPods in the ",(0,o.jsx)(n.code,{children:"projectcontour"})," namespace reaching the frontend and backend. A default-deny that forgets to\nallow ",(0,o.jsx)(n.code,{children:"projectcontour"})," would silently break Ingress routing \u2014 the app would look up and pass its health\nchecks while every external request 503'd. This is the single most common way a well-meaning NetworkPolicy\ntakes down a working app, and the lab makes you prove Ingress still routes after the policy is applied."]}),"\n",(0,o.jsx)(n.h2,{id:"where-this-leaves-the-app",children:"Where this leaves the app"}),"\n",(0,o.jsx)(n.p,{children:"At the end of this module's lab, Fernwood is hardened without a single change to its application code. Its\nconfiguration lives in a ConfigMap and a Secret you can permission independently. A scoped Service Account\nproves the RBAC boundary works. And a default-deny NetworkPolicy, with named exceptions, means the only Pod\nthat can reach Postgres is the backend \u2014 while the M7 front door keeps serving traffic. That is the shape\nof a service that could pass a review."}),"\n",(0,o.jsx)(n.p,{children:"The next lesson steps back from the mechanics. You have spent eight modules building one small system into\na set of independent, separately-deployed, network-isolated services. Lesson 2 names what you actually\nbuilt \u2014 the microservices patterns hiding in plain sight across the whole course \u2014 and is honest about what\nthat architecture costs."})]})}function u(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},7684(e,n,t){t.d(n,{A:()=>i});var s=t(4848);t(6540);var o=t(6497);function i({src:e,title:n="Slides"}){let t=(0,o.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,s.jsx)("a",{className:"full_PrDQ",href:t,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:t,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>r});var s=t(6540);let o={},i=s.createContext(o);function a(e){let n=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),s.createElement(i.Provider,{value:n},e.children)}}}]);